    """
    m=sp.MutableDenseMatrix(matrix)
    if desired<m.rank():
        keep=[]
        for i in range(m.rows):
            if len(keep)<desired and sp.Matrix([list(matrix.row(j)) for j in keep+[i]]).rank()>len(keep):keep.append(i)
