    """Visible workload and exclusions within one complete source bank."""
    q=rec['question'];bank=matrices(q);r=target(q)
    return (rec['generation']['bank_profile'],r,
            tuple((k,m.shape) for k,m in sorted(bank.items())),
            tuple(k for k,m in sorted(bank.items()) if min(m.shape)<r),
            len(q[':question/answer-fields']),rec['generation']['choice_profile'])
def batch(level,count,seed=0):
    if level not in SUPPORTED_LEVELS:raise ValueError('Unsupported difficulty: '+level)
    candidates=catalog();random.Random(seed).shuffle(candidates)
    # Role reassignment removes label cues, but does not inflate semantic capacity.
    records=[];seen=set()
    for rec in candidates:
        fp=rec['generation']['mathematical_fingerprint']
        if fp not in seen:seen.add(fp);records.append(rec)
    if type(count) is not int or count<0 or count>len(records):raise ValueError('Finite variant limit: '+str(len(records)))
    selected=records[:count]
    # Allocate complete decision sets, rather than seeking opposite answers in
    # a fixed number of slots. For two eligible subset candidates, the latter
    # rule forces singleton answers and makes one rank inspection redundant.
    by_profile={}
    for rec in records:by_profile.setdefault(rec['generation']['bank_profile'],[]).append(rec)
    prefix_counts={sid:sum(r['generation']['bank_profile']==sid for r in selected) for sid in by_profile}
    profiles=sorted(by_profile,key=lambda sid:prefix_counts[sid]<2)
    blocks=[]
    prefix_ids={rec['question'][':question/id'] for rec in selected}
    for sid in profiles:
        old=by_profile[sid]
        group=decision_group(old[0])
        pool=[rec for rec in candidates if decision_group(rec)==group]
        pool.sort(key=lambda rec:rec['question'][':question/id'] not in prefix_ids)
        block=[];used=set()
        for rec in pool:
            fp=rec['generation']['mathematical_fingerprint']
            if fp not in used:used.add(fp);block.append(rec)
        assert len(block)==len(old), 'Visible subgroup must retain semantic capacity'
        blocks.append(block)

    @lru_cache(None)
    def allocate(index,remaining):
        if remaining==0:return ()
        if index==len(blocks):return None
        # Repeated profiles receive every decision case. Short requests may use
        # a single representative, never an incomplete repeated subset block.
        for size in (len(blocks[index]),1,0):
            if size>remaining:continue
            rest=allocate(index+1,remaining-size)
            if rest is not None:return (size,)+rest
        return None
    sizes=allocate(0,count)
    if sizes is None:raise ValueError('Cannot allocate complete decision sets')
    result=[rec for block,size in zip(blocks,sizes) for rec in block[:size]]
    # Interleave decision cases; their adjacency/order must not reveal the key.
    random.Random(seed).shuffle(result)
    return result
